-- Синтетическая история приёмов за октябрь 2026 для экрана аналитики.

--changeset quietclinic:006 dbms:postgresql
ALTER TABLE appointment DROP CONSTRAINT appointment_no_overlap;
ALTER TABLE appointment
  ADD CONSTRAINT appointment_no_overlap
  EXCLUDE USING gist (
    practitioner_id WITH =,
    tstzrange(starts_at, ends_at, '[)') WITH &&
  )
  WHERE (status IN ('BOOKED','CONFIRMED','ARRIVED','IN_PROGRESS','COMPLETED'));
